// Game UI catalog components. Each one is self-contained HTML+CSS with a unique class prefix (g*-).
// Built to survive the Roblox exporter: real elements with solid colors / simple linear gradients,
// borders and radii; every visible text lives in its own element; bars are an outer div + an inner div
// with a % width; inline SVG icons are decorative only. Animations are extras, the static look is complete.
const RM = sel => `@media(prefers-reduced-motion:reduce){${sel}{animation:none!important;transition:none!important}}`;
const F = 'font-family:system-ui,-apple-system,"Segoe UI",sans-serif';
const M = 'font-family:ui-monospace,"SF Mono",Consolas,monospace';
const C = 'font-family:"Trebuchet MS","Arial Rounded MT Bold",system-ui,sans-serif';
const G = (body, s = 28) => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" aria-hidden="true">${body}</svg>`;
// Coin = a real element (exports as a gold circle); gems & items are decorative SVG.
const COIN = (s = 22) => `<span style="display:inline-block;flex:none;width:${s}px;height:${s}px;box-sizing:border-box;border:${s > 20 ? 3 : 2}px solid #a16207;border-radius:50%;background:linear-gradient(#fde047,#eab308);vertical-align:middle"></span>`;
